import{_ as r,o as d,c as o,ag as a}from"./chunks/framework.D2veAa-g.js";const u=JSON.parse('{"title":"架构师-备考 案例分析-系统架构设计真题回顾","description":"","frontmatter":{"title":"架构师-备考 案例分析-系统架构设计真题回顾"},"headers":[],"relativePath":"案例分析/系统架构设计真题回顾.md","filePath":"案例分析/系统架构设计真题回顾.md","lastUpdated":null}'),n={name:"案例分析/系统架构设计真题回顾.md"};function s(e,t,h,l,g,i){return d(),o("div",null,[...t[0]||(t[0]=[a('<h2 id="考点清单" tabindex="-1">考点清单 <a class="header-anchor" href="#考点清单" aria-label="Permalink to &quot;考点清单&quot;">​</a></h2><ul><li>[x] 断路器模式 3 状态</li><li>[x] C/S 与 B/S 架构层次</li><li>[x] 质量属性 6 要素 + 场景识别</li><li>[x] ATAM 效用树结构 + 3 种场景类型</li><li>[x] 敏感点 vs 权衡点 vs 风险点</li><li>[x] ISO 25010 可靠性 4 子特性</li><li>[x] 微服务 vs 单体架构对比</li><li>[x] ping/echo vs 心跳</li><li>[x] WSDL/SOAP/UDDI 角色分工</li><li>[x] 架构风格分类与辨析</li><li>[x] ABSD / DSSA</li><li>[x] 体系结构演化 6 步骤</li></ul><h2 id="笔记" tabindex="-1">笔记 <a class="header-anchor" href="#笔记" aria-label="Permalink to &quot;笔记&quot;">​</a></h2><h3 id="一、断路器模式-3-状态-★" tabindex="-1">一、断路器模式 3 状态 ★ <a class="header-anchor" href="#一、断路器模式-3-状态-★" aria-label="Permalink to &quot;一、断路器模式 3 状态 ★&quot;">​</a></h3><table tabindex="0"><thead><tr><th>状态</th><th>行为</th></tr></thead><tbody><tr><td><strong>关闭（Closed）</strong></td><td>请求正常通过，断路器不介入</td></tr><tr><td><strong>打开（Open）</strong></td><td>错误超阈值，请求快速失败</td></tr><tr><td><strong>半打开（Half-Open）</strong></td><td>打开一段时间后，尝试放行部分请求检测服务是否恢复</td></tr></tbody></table><hr><h3 id="二、c-s-与-b-s-架构层次" tabindex="-1">二、C/S 与 B/S 架构层次 <a class="header-anchor" href="#二、c-s-与-b-s-架构层次" aria-label="Permalink to &quot;二、C/S 与 B/S 架构层次&quot;">​</a></h3><table tabindex="0"><thead><tr><th>架构</th><th>层次</th></tr></thead><tbody><tr><td><strong>两层 C/S</strong></td><td>客户端 + 数据库服务器</td></tr><tr><td><strong>三层 C/S</strong></td><td>客户端 + 应用服务器 + 数据库服务器（表现层/业务逻辑层/数据访问层）</td></tr><tr><td><strong>B/S</strong></td><td>特殊的三层架构（浏览器 - Web 服务器 - 数据库）</td></tr></tbody></table><blockquote><p>&quot;功能层&quot;不是标准术语，标准三层：表现层（UI）、业务逻辑层（BLL）、数据访问层（DAL）。</p></blockquote><hr><h3 id="三、质量属性-6-要素-★" tabindex="-1">三、质量属性 6 要素 ★ <a class="header-anchor" href="#三、质量属性-6-要素-★" aria-label="Permalink to &quot;三、质量属性 6 要素 ★&quot;">​</a></h3><table tabindex="0"><thead><tr><th>要素</th><th>说明</th></tr></thead><tbody><tr><td><strong>刺激源</strong></td><td>产生刺激的物理/逻辑实体</td></tr><tr><td><strong>刺激</strong></td><td>触发事件</td></tr><tr><td><strong>环境</strong></td><td>刺激发生时系统所处条件</td></tr><tr><td><strong>制品</strong></td><td>被刺激的系统或部分</td></tr><tr><td><strong>响应</strong></td><td>刺激到达后采取的行动</td></tr><tr><td><strong>响应度量</strong></td><td>可测量的指标</td></tr></tbody></table><p><strong>质量属性场景识别示例：</strong></p><table tabindex="0"><thead><tr><th>场景</th><th>质量属性</th></tr></thead><tbody><tr><td>系统业务故障时 3 秒内启动备用系统</td><td><strong>可用性</strong></td></tr><tr><td>用户输入→处理→展示结果</td><td><strong>功能性</strong></td></tr><tr><td>数据导入导出 1 分钟内完成</td><td><strong>性能</strong></td></tr><tr><td>用户量增长 3 天内扩展空间</td><td><strong>可修改性</strong></td></tr><tr><td>支持 3 国语言 + 搜索自动补全</td><td><strong>易用性</strong></td></tr><tr><td>云服务器故障 2 秒内切换</td><td><strong>可用性</strong></td></tr><tr><td>远程在线诊断查看问题</td><td><strong>可测试性</strong></td></tr><tr><td>1 分钟检测故障 + 1 小时恢复</td><td><strong>可靠性</strong></td></tr><tr><td>多因素认证（密码+指纹+面容+IC卡）</td><td><strong>安全性</strong></td></tr></tbody></table><hr><h3 id="四、atam-效用树-★" tabindex="-1">四、ATAM 效用树 ★ <a class="header-anchor" href="#四、atam-效用树-★" aria-label="Permalink to &quot;四、ATAM 效用树 ★&quot;">​</a></h3><p><strong>结构（根→叶）</strong>：树根（总体目标）→ 质量属性（性能/安全等）→ 属性分类（如性能→延迟/吞吐量）→ 质量属性场景（叶子节点）。</p><blockquote><p>效用树是<strong>评估工具</strong>，而非设计工具。</p></blockquote><p><strong>ATAM 3 种场景：</strong></p><ul><li><strong>用例场景</strong>：正常操作下的预期使用方式</li><li><strong>增长场景</strong>：适应未来变化的架构修改</li><li><strong>探索性场景</strong>：极端情况（高负载/故障/攻击）</li></ul><p><strong>质量属性评估方法：</strong></p><table tabindex="0"><thead><tr><th>方法</th><th>特点</th><th>工具</th></tr></thead><tbody><tr><td><strong>SAAM</strong></td><td>评估可修改性，使用场景</td><td>场景</td></tr><tr><td><strong>ATAM</strong></td><td>综合架构评估，权衡分析</td><td><strong>效用树</strong></td></tr><tr><td><strong>CBAM</strong></td><td>成本效益分析</td><td>ATAM 后续补充</td></tr></tbody></table><hr><h3 id="五、敏感点-vs-权衡点-vs-风险点-★" tabindex="-1">五、敏感点 vs 权衡点 vs 风险点 ★ <a class="header-anchor" href="#五、敏感点-vs-权衡点-vs-风险点-★" aria-label="Permalink to &quot;五、敏感点 vs 权衡点 vs 风险点 ★&quot;">​</a></h3><table tabindex="0"><thead><tr><th>概念</th><th>定义</th></tr></thead><tbody><tr><td><strong>敏感点</strong></td><td>为实现某个特定质量属性产生影响的设计决策点</td></tr><tr><td><strong>权衡点</strong></td><td>影响<strong>多个</strong>质量属性的敏感点，调整时对其他属性有负面影响</td></tr><tr><td><strong>风险点</strong></td><td>架构设计中可能导致项目失败的设计决策</td></tr><tr><td><strong>非风险点</strong></td><td>与风险点相对</td></tr></tbody></table><hr><h3 id="六、iso-25010-可靠性-4-子特性-★" tabindex="-1">六、ISO 25010 可靠性 4 子特性 ★ <a class="header-anchor" href="#六、iso-25010-可靠性-4-子特性-★" aria-label="Permalink to &quot;六、ISO 25010 可靠性 4 子特性 ★&quot;">​</a></h3><blockquote><p>ISO 25010 中，&quot;可用性&quot;是&quot;可靠性&quot;的<strong>子特性</strong>。</p></blockquote><table tabindex="0"><thead><tr><th>子特性</th><th>说明</th><th>通俗理解</th></tr></thead><tbody><tr><td><strong>成熟性（Maturity）</strong></td><td>正常运行时满足可靠性要求的程度</td><td>&quot;别主动出错&quot;</td></tr><tr><td><strong>可用性（Availability）</strong></td><td>系统需要时可操作和访问的程度</td><td>&quot;需要时就能用&quot;</td></tr><tr><td><strong>容错性（Fault Tolerance）</strong></td><td>存在故障仍能按预期运行</td><td>&quot;出错了也别趴窝&quot;</td></tr><tr><td><strong>可恢复性（Recoverability）</strong></td><td>故障后恢复数据并达到预期状态</td><td>&quot;趴窝了快速爬起来&quot;</td></tr></tbody></table><blockquote><p>&quot;稳定性&quot;在 ISO 25010 中非官方术语，常被误归于性能效率。</p></blockquote><p><strong>易分析性</strong>属于可维护性子特性（非易用性）。<strong>数据延迟时间</strong>是性能效率指标，非可用性指标。</p><hr><h3 id="七、微服务-vs-单体架构-★" tabindex="-1">七、微服务 vs 单体架构 ★ <a class="header-anchor" href="#七、微服务-vs-单体架构-★" aria-label="Permalink to &quot;七、微服务 vs 单体架构 ★&quot;">​</a></h3><table tabindex="0"><thead><tr><th>维度</th><th>单体架构</th><th>微服务架构</th></tr></thead><tbody><tr><td><strong>代码结构</strong></td><td>单一代码库，模块紧耦合</td><td>多独立代码库，服务松耦合</td></tr><tr><td><strong>数据管理</strong></td><td>共享数据库，ACID 事务</td><td>独立数据库，需处理最终一致性（BASE）</td></tr><tr><td><strong>部署方式</strong></td><td>整体打包（WAR）</td><td>独立容器化（Docker+K8s）</td></tr><tr><td><strong>扩展性</strong></td><td>垂直扩展（Scale-Up）</td><td>水平扩展（Scale-Out）</td></tr><tr><td><strong>技术栈</strong></td><td>统一</td><td>多语言混合（Polyglot）</td></tr></tbody></table><table tabindex="0"><thead><tr><th>架构</th><th>适用场景</th></tr></thead><tbody><tr><td>单体</td><td>小项目（&lt;10人）、快速验证、强一致性要求（银行核心）</td></tr><tr><td>微服务</td><td>大型系统（&gt;50人）、快速迭代（电商、社交网络）</td></tr></tbody></table><p><strong>微服务缺点</strong>：复杂度高、部署测试成本高、运维成本高（链路追踪等）、分布式事务问题。</p><hr><h3 id="八、ping-echo-vs-心跳" tabindex="-1">八、ping/echo vs 心跳 <a class="header-anchor" href="#八、ping-echo-vs-心跳" aria-label="Permalink to &quot;八、ping/echo vs 心跳&quot;">​</a></h3><table tabindex="0"><thead><tr><th>机制</th><th>特点</th><th>频率</th><th>用途</th></tr></thead><tbody><tr><td><strong>Ping/Echo</strong></td><td>客户端发 ping，服务器回 echo</td><td>可能需要更频繁</td><td>检测连接状态</td></tr><tr><td><strong>心跳（Heartbeat）</strong></td><td>定期发心跳包，对方回复确认</td><td>较低频率</td><td>维持长连接</td></tr></tbody></table><blockquote><p>心跳资源利用率更低：频率低、数据量小、维持活跃状态。</p></blockquote><hr><h3 id="九、wsdl-soap-uddi-★" tabindex="-1">九、WSDL / SOAP / UDDI ★ <a class="header-anchor" href="#九、wsdl-soap-uddi-★" aria-label="Permalink to &quot;九、WSDL / SOAP / UDDI ★&quot;">​</a></h3><table tabindex="0"><thead><tr><th>协议</th><th>角色</th><th>类比</th></tr></thead><tbody><tr><td><strong>WSDL</strong></td><td>服务<strong>接口说明书</strong>（what/how/where）</td><td>API 合同</td></tr><tr><td><strong>SOAP</strong></td><td>服务间通信<strong>数据传输规范</strong>（Envelope + Header + Body）</td><td>商务信函/国际快递包裹</td></tr><tr><td><strong>UDDI</strong></td><td>服务<strong>注册中心</strong>，发布和发现</td><td>电话簿</td></tr></tbody></table><p><strong>协同流程</strong>：提供者发 WSDL 到 UDDI → 消费者查 UDDI 获取 WSDL → 根据 WSDL 生成 SOAP 请求 → 发送 SOAP 消息。</p><hr><h3 id="十、架构风格分类与辨析-★" tabindex="-1">十、架构风格分类与辨析 ★ <a class="header-anchor" href="#十、架构风格分类与辨析-★" aria-label="Permalink to &quot;十、架构风格分类与辨析 ★&quot;">​</a></h3><table tabindex="0"><thead><tr><th>大类</th><th>子风格</th><th>易错点</th></tr></thead><tbody><tr><td><strong>调用返回</strong></td><td>主程序子程序、面向对象、层次</td><td><strong>黑板不属于调用返回</strong>（由数据状态驱动）</td></tr><tr><td><strong>数据流</strong></td><td>管道-过滤器、批处理</td><td>管道过滤器<strong>可并行执行</strong>；批处理<strong>顺序执行</strong></td></tr><tr><td><strong>仓库风格</strong></td><td>黑板（特殊仓库）、中央数据结构</td><td>黑板 ≠ 管道-过滤器；管道过滤器不是仓库子风格</td></tr><tr><td><strong>虚拟机</strong></td><td>解释器、基于规则的系统</td><td>基于规则系统构建在解释器之上</td></tr><tr><td><strong>独立构件</strong></td><td>进程通信、事件驱动</td><td>进程通信连接件=<strong>消息传递</strong>；事件驱动=<strong>松耦合</strong></td></tr></tbody></table><blockquote><p>仓库风格核心：共享的<strong>中央数据结构</strong>。黑板三要素：黑板 + 知识源 + 控制器。</p></blockquote><hr><h3 id="十一、absd-基于属性的软件设计" tabindex="-1">十一、ABSD（基于属性的软件设计） <a class="header-anchor" href="#十一、absd-基于属性的软件设计" aria-label="Permalink to &quot;十一、ABSD（基于属性的软件设计）&quot;">​</a></h3><p>需求来源 3 类：</p><ol><li>系统的<strong>业务目标</strong></li><li>系统的<strong>质量目标</strong></li><li>系统开发人员的<strong>业务目标</strong>（预算、周期、技术栈、可维护性等）</li></ol><hr><h3 id="十二、dssa-特定领域软件架构" tabindex="-1">十二、DSSA（特定领域软件架构） <a class="header-anchor" href="#十二、dssa-特定领域软件架构" aria-label="Permalink to &quot;十二、DSSA（特定领域软件架构）&quot;">​</a></h3><table tabindex="0"><thead><tr><th>知识点</th><th>说明</th></tr></thead><tbody><tr><td>三阶段</td><td>领域分析 → 领域设计 → 领域实现</td></tr><tr><td>过程模型</td><td>迭代精化，与<strong>螺旋模型</strong>相似（非原型模型）</td></tr><tr><td>领域专家角色</td><td>领域分析员、领域设计员、领域实现员</td></tr></tbody></table><hr><h3 id="十三、互操作性与网格计算" tabindex="-1">十三、互操作性与网格计算 <a class="header-anchor" href="#十三、互操作性与网格计算" aria-label="Permalink to &quot;十三、互操作性与网格计算&quot;">​</a></h3><p><strong>最具代表性组合</strong>：<strong>五层沙漏模型</strong> + <strong>开放式 Web Service</strong>（基于开放标准实现异构资源互操作）。</p><hr><h3 id="十四、体系结构演化-6-步骤" tabindex="-1">十四、体系结构演化 6 步骤 <a class="header-anchor" href="#十四、体系结构演化-6-步骤" aria-label="Permalink to &quot;十四、体系结构演化 6 步骤&quot;">​</a></h3><p>分析变化 → 制定计划 → 修改构件 → <strong>更新构件间交互关系</strong> → 组装测试 → 评审。</p><hr><h3 id="十五、其他速记" tabindex="-1">十五、其他速记 <a class="header-anchor" href="#十五、其他速记" aria-label="Permalink to &quot;十五、其他速记&quot;">​</a></h3><table tabindex="0"><thead><tr><th>知识点</th><th>速记</th></tr></thead><tbody><tr><td>ESB</td><td>SOA 核心基础设施，实现位置透明性和通信协议解耦</td></tr><tr><td>DDD 领域层</td><td>承载业务规则和状态，纯业务逻辑，不含技术实现细节</td></tr><tr><td>SOAP 信封编码</td><td>信封和 XML 编码定义在<strong>不同</strong>命名空间</td></tr><tr><td>基于度量的评估</td><td>最终推导的是<strong>质量属性</strong></td></tr><tr><td>可修改性 vs 可扩展性</td><td>可修改性=适应新需求/变化；可扩展性=容量增长</td></tr></tbody></table>',64)])])}const c=r(n,[["render",s]]);export{u as __pageData,c as default};
